"""Nạp dữ liệu dùng chung cho B2-B4. Nguồn: te_daily.parquet (TE daily, source tường minh), data/bq_cache/ticker (Close điều chỉnh),
data/bq_cache/universe_pit (PIT universe), data/bq_cache/ticker_financial.parquet (Release_Date = ngày công bố PIT)."""
import pandas as pd, numpy as np, glob, os
W='/home/trido/thanhdt/WorkingClaude'; O=os.path.dirname(os.path.abspath(__file__))
def te():
    d=pd.read_parquet(f'{O}/te_daily.parquet'); return d.pivot(index='observation_date',columns='metric_key',values='value').sort_index()
def cmap(tiers=('A','B')):
    m=pd.read_csv(f'{O}/commodity_map_te.csv'); return m[m.tier.isin(tiers)&(m.ticker!='-')]
_px=None
def px():
    global _px
    if _px is None:
[REDACTED]t=pd.concat([pd.read_parquet(f,columns=['ticker','time','Close']) for f in sorted(glob.glob(f'{W}/data/bq_cache/ticker/*.parquet'))])
[REDACTED]t['time']=pd.to_datetime(t.time); _px=t.pivot_table(index='time',columns='ticker',values='Close').sort_index()
    return _px
def univ():
    u=pd.concat([pd.read_parquet(f,columns=['ticker','time','in_universe']) for f in sorted(glob.glob(f'{W}/data/bq_cache/universe_pit/*.parquet'))])
    u['time']=pd.to_datetime(u.time); return u[u.in_universe==True].pivot_table(index='time',columns='ticker',values='in_universe',aggfunc='first').notna().sort_index()
def fin():
    f=pd.read_parquet(f'{W}/data/bq_cache/ticker_financial.parquet',columns=['ticker','quarter','Release_Date','Revenue_P0','Revenue_P1','Revenue_P4','NP_P0','NP_P1','NP_P4','GPM_P0','GPM_P1','GPM_P4','PE','PCF'])
    f['Release_Date']=pd.to_datetime(f.Release_Date)
    f=f.sort_values('Release_Date').drop_duplicates(['ticker','quarter'],keep='first')  # bản công bố ĐẦU TIÊN (chống restate)
    q=pd.PeriodIndex(f.quarter.str.replace('Q','Q'),freq='Q'); f['qend']=q.end_time.normalize()
    return f
def bench(px,u):
    r=px.pct_change(fill_method=None).where(u.reindex(px.index).fillna(False).shift(1).fillna(False))
    return r.mean(axis=1).fillna(0)   # EW universe_pit, thành viên tại t-1
"""B2: giá TB quý hàng hoá (TE daily, biết từ qend+1 phiên) -> KQKD quý đó (công bố sau) + phản ứng giá quanh công bố."""
import pandas as pd, numpy as np, json
from scipy.stats import spearmanr
from common import *
rng=np.random.default_rng(20261026)
T=te(); P=px(); U=univ(); F=fin(); B=bench(P,U); Bc=(1+B).cumprod()
M=cmap(('A','B'))
# giá TB theo quý lịch; chỉ quý có >=40 quan sát (đủ phiên) — quý đầu 2016Q4 bị loại tự nhiên
qa=T.resample('QE').mean(); qn=T.resample('QE').count()
qa=qa.where(qn>=40)
idx=P.index
def at(d):  # phiên đầu tiên >= d
    i=idx.searchsorted(d); return idx[i] if i<len(idx) else None
def ret(tk,d0,d1):
    if d0 is None or d1 is None: return np.nan
    a,b=P.at[d0,tk],P.at[d1,tk]
    return b/a-1-(Bc[d1]/Bc[d0]-1) if a>0 and b>0 else np.nan
rows=[]
for _,m in M.iterrows():
    s=qa[m.te_metric_key]
    yoy=np.log(s/s.shift(4)); qoq=np.log(s/s.shift(1))
    f=F[F.ticker==m.ticker]
    for _,r in f.iterrows():
[REDACTED]qe=r.qend
[REDACTED]if qe not in s.index or pd.isna(yoy.get(qe)) : continue
[REDACTED]sig_day=at(qe+pd.Timedelta(days=2))[REDACTED]  # TE cập nhật 23:00 ICT => trễ >=1 phiên sau obs cuối quý
[REDACTED]if sig_day is None or r.Release_Date<=sig_day: continue   # chỉ giữ khi tín hiệu có TRƯỚC công bố
[REDACTED]if sig_day not in U.index or not U.at[sig_day,m.ticker] if m.ticker in U.columns else True: continue
[REDACTED]pre_end=idx[idx.searchsorted(r.Release_Date)-1]       # phiên cuối trước ngày công bố
[REDACTED]te_=at(r.Release_Date+pd.Timedelta(days=1))[REDACTED]   # vào lệnh: phiên đầu SAU ngày công bố
[REDACTED]i=idx.get_loc(te_) if te_ is not None else None
[REDACTED]e60=idx[i+60] if i is not None and i+60<len(idx) else None
[REDACTED]rev=np.log(r.Revenue_P0/r.Revenue_P4) if r.Revenue_P0>0 and r.Revenue_P4>0 else np.nan
[REDACTED]rows.append(dict(ticker=m.ticker,family=m.family,sign=m.sign,tier=m.tier,quarter=r.quarter,qend=qe,release=r.Release_Date,
[REDACTED]    lag_days=(r.Release_Date-qe).days,c_yoy=yoy[qe]*m.sign,c_qoq=qoq[qe]*m.sign,
[REDACTED]    rev_yoy=rev, gpm_d=(r.GPM_P0-r.GPM_P4) if abs(r.GPM_P0)<5 and abs(r.GPM_P4)<5 else np.nan,
[REDACTED]    np_d=(r.NP_P0-r.NP_P4)/r.Revenue_P4 if r.Revenue_P4>0 else np.nan,
[REDACTED]    np_qd=(r.NP_P0-r.NP_P1)/r.Revenue_P1 if r.Revenue_P1>0 else np.nan,
[REDACTED]    pre=ret(m.ticker,sig_day,pre_end), ann=ret(m.ticker,pre_end,te_), post60=ret(m.ticker,te_,e60)))
D=pd.DataFrame(rows)
for c in ['np_d','np_qd']: D[c]=D[c].clip(-0.5,0.5)
D.to_csv('b2_panel.csv',index=False)
print('panel rows',len(D),'tickers',D.ticker.nunique(),'quarters',D.quarter.nunique(), 'lag median',D.lag_days.median())
# family-quarter aggregation (N độc lập = họ x quý)
G=D.groupby(['family','tier','quarter']).agg(c_yoy=('c_yoy','first'),c_qoq=('c_qoq','first'),**{k:(k,'median') for k in ['rev_yoy','gpm_d','np_d','np_qd','pre','ann','post60']},n=('ticker','count')).reset_index()
G['IS']=G.quarter<'2023Q1'
G.to_csv('b2_famq.csv',index=False)
def ic(g,x,y):
    g=g[[x,y]].dropna(); 
    return (spearmanr(g[x],g[y])[0], len(g)) if len(g)>=8 else (np.nan,len(g))
out=[]
for (fam,tier),g in G.groupby(['family','tier']):
    for x,y in [('c_yoy','rev_yoy'),('c_yoy','gpm_d'),('c_yoy','np_d'),('c_qoq','np_qd'),('c_yoy','pre'),('c_yoy','ann'),('c_yoy','post60')]:
[REDACTED]r,n=ic(g,x,y); ri,ni=ic(g[g.IS],x,y); ro,no=ic(g[~g.IS],x,y)
[REDACTED]out.append(dict(family=fam,tier=tier,x=x,y=y,ic=r,n=n,ic_IS=ri,n_IS=ni,ic_OOS=ro,n_OOS=no))
O_=pd.DataFrame(out); O_.to_csv('b2_ic_family.csv',index=False)
pd.set_option('display.width',250)
print(O_.pivot_table(index=['tier','family'],columns='y',values='ic').round(2).to_string())
print(O_.pivot_table(index=['tier','family'],columns='y',values='n').to_string())
# pooled tier A: rank-IC trung bình theo họ, bootstrap theo QUÝ (giữ tương quan chéo họ cùng quý)
A=G[G.tier=='A'].copy()
def pooled(A,x,y):
    A=A.dropna(subset=[x,y]).copy()
    A['rx']=A.groupby('family')[x].rank(pct=True)-.5; A['ry']=A.groupby('family')[y].rank(pct=True)-.5
    est=np.corrcoef(A.rx,A.ry)[0,1]
    qs=A.quarter.unique(); bs=[]
    byq={q:A[A.quarter==q] for q in qs}
    for _ in range(5000):
[REDACTED]s=pd.concat([byq[q] for q in rng.choice(qs,len(qs))]); bs.append(np.corrcoef(s.rx,s.ry)[0,1])
    # permutation: xáo c trong từng họ theo khối quý -> phá liên hệ thời gian
    perm=[]
    for _ in range(2000):
[REDACTED]B_=A.copy(); B_['rx']=B_.groupby('family').rx.transform(lambda v: np.roll(v.values, rng.integers(1,len(v))))
[REDACTED]perm.append(np.corrcoef(B_.rx,B_.ry)[0,1])
    p=(np.sum(np.abs(perm)>=abs(est))+1)/(len(perm)+1)
    return dict(x=x,y=y,ic=round(est,3),ci90=[round(np.percentile(bs,5),3),round(np.percentile(bs,95),3)],p_circshift=round(p,4),n_famq=len(A),n_quarters=len(qs),n_fam=A.family.nunique())
res=[]
for x,y in [('c_yoy','rev_yoy'),('c_yoy','gpm_d'),('c_yoy','np_d'),('c_qoq','np_qd'),('c_yoy','pre'),('c_yoy','ann'),('c_yoy','post60')]:
    for lab,sub in [('ALL',A),('IS',A[A.IS]),('OOS',A[~A.IS])]:
[REDACTED]r=pooled(sub,x,y); r['split']=lab; res.append(r); print(r)
json.dump(res,open('b2_pooled.json','w'),indent=1,default=str)
"""B2b: tách surprise (np_d) thành phần hàng hoá GIẢI THÍCH được (biết trước công bố) vs phần dư; phần nào thị trường phản ứng/ drift?
Đơn vị: ticker-quý; hồi quy chuẩn hoá theo rank trong họ; SE bootstrap theo QUÝ (cụm)."""
import pandas as pd, numpy as np, json
rng=np.random.default_rng(7)
D=pd.read_csv('b2_panel.csv'); D=D[D.tier=='A'].dropna(subset=['c_yoy','np_d','ann']).copy()
D['IS']=D.quarter<'2023Q1'
r=lambda s: s.rank(pct=True)-.5
# phần giải thích: fit np_d ~ c_yoy trong TỪNG họ trên dữ liệu QUÁ KHỨ (expanding, chỉ quý < quý hiện tại) => PIT
D=D.sort_values('qend'); D['np_hat']=np.nan
for fam,g in D.groupby('family'):
    for q in g.quarter.unique():
[REDACTED]past=g[g.quarter<q]
[REDACTED]if past.quarter.nunique()<6: continue
[REDACTED]b=np.polyfit(past.c_yoy,past.np_d,1)
[REDACTED]D.loc[(D.family==fam)&(D.quarter==q),'np_hat']=np.polyval(b,D.loc[(D.family==fam)&(D.quarter==q),'c_yoy'])
D=D.dropna(subset=['np_hat']); D['np_res']=D.np_d-D.np_hat
print('n ticker-quy',len(D),'quy',D.quarter.nunique())
print('IC(np_hat,np_d) PIT expanding:',round(D[['np_hat','np_d']].corr('spearman').iloc[0,1],3))
def reg(df,y,xs,B=3000):
    Z=df.copy()
    for c in xs+[y]: Z[c]=Z.groupby('family')[c].transform(r)
    X=np.c_[np.ones(len(Z)),Z[xs].values]; beta=np.linalg.lstsq(X,Z[y].values,rcond=None)[0]
    qs=Z.quarter.unique(); byq={q:Z[Z.quarter==q] for q in qs}; bs=[]
    for _ in range(B):
[REDACTED]s=pd.concat([byq[q] for q in rng.choice(qs,len(qs))]); Xs=np.c_[np.ones(len(s)),s[xs].values]
[REDACTED]bs.append(np.linalg.lstsq(Xs,s[y].values,rcond=None)[0])
    bs=np.array(bs); se=bs.std(0)
    return {x:dict(b=round(beta[i+1],3),t=round(beta[i+1]/se[i+1],2)) for i,x in enumerate(xs)}|dict(n=len(Z),nq=len(qs))
out={}
for y in ['ann','post60','pre']:
    for lab,sub in [('ALL',D),('IS',D[D.IS]),('OOS',D[~D.IS])]:
[REDACTED]s=sub.dropna(subset=[y]); out[f'{y}|{lab}|np_d']=reg(s,y,['np_d']); out[f'{y}|{lab}|hat+res']=reg(s,y,['np_hat','np_res'])
for k,v in out.items(): print(k,v)
json.dump(out,open('b2_decomp.json','w'),indent=1)
